"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["39840"],{54959(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fase_com_preliminar_sem_definitivo","status":422,"titulo":"A fase publica resultado preliminar sem o definitivo do mesmo tipo de ato"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fase_com_preliminar_sem_definitivo","requisitos":["UNI-REQ-0157","UNI-REQ-0211"],"oQueAconteceu":["Uma fase do cronograma publica o resultado **preliminar** de um tipo de ato e n\xe3o publica o resultado **definitivo** do mesmo tipo. O preliminar abre um ciclo de recurso, e sem o definitivo a mat\xe9ria fica aberta, sem desfecho previsto para o candidato (UNI-REQ-0157 e UNI-REQ-0211). Toda fase que publica um resultado preliminar publica, nela mesma, o definitivo do mesmo tipo de ato: n\xe3o existe outra fase que conclua o ciclo. Um definitivo de outro tipo de ato n\xe3o fecha o ciclo, porque a mat\xe9ria \xe9 o tipo de ato.","A confer\xeancia roda na publica\xe7\xe3o inicial e na retifica\xe7\xe3o em ato \xfanico; a grava\xe7\xe3o do cronograma n\xe3o a faz. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na lista `errors[]`. O campo \xe9 `/cronograma/fases/{i}/produtos`, em que `i` \xe9 a posi\xe7\xe3o da fase no documento, e a resposta traz o c\xf3digo da fase em `identificadores`, no formato `[{\\"lista\\": \\"fases\\", \\"identificador\\": \\"<c\xf3digo da fase>\\"}]`. Se a lista de produtos da fase tem parte recusada, a confer\xeancia espera essa parte ser corrigida.","A mensagem da resposta diz: \\"A fase \'*c\xf3digo da fase*\' publica o resultado preliminar do ato \'*tipo de ato*\' e n\xe3o publica o definitivo do mesmo tipo. Publique o resultado definitivo na pr\xf3pria fase.\\""],"comoResolver":["Acrescente aos produtos da fase o resultado definitivo do mesmo tipo de ato do preliminar, com o papel definitivo. Se o edital n\xe3o quer ciclo de recurso para aquela mat\xe9ria, retire o resultado preliminar. O painel de conformidade mostra esta pend\xeancia antes da publica\xe7\xe3o, no item `cronograma_conclusao_do_ciclo_recursal`. Para a etapa, a recusa equivalente \xe9 [etapa com preliminar sem definitivo](/erros/uniplus.selecao.processo_seletivo.etapa_com_preliminar_sem_definitivo)."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);